import * as vscode from 'vscode';
import type { CompileResult } from '@owt/compiler';
import { LivePreview, errorMessage } from './preview';

export const COMPILED_SCHEME = 'owt-compiled';

type Compiler = typeof import('@owt/compiler');

let compilerPromise: Promise<Compiler> | undefined;

/** The compiler is bundled into the extension but only evaluated on first use. */
function loadCompiler(): Promise<Compiler> {
  compilerPromise ??= import('@owt/compiler');
  return compilerPromise;
}

/** `owt-compiled:` documents showing the JavaScript (and CSS) generated by `@owt/compiler`. */
export function createCompiledOutputPreview(): LivePreview {
  return new LivePreview({
    scheme: COMPILED_SCHEME,
    extension: '.js',
    languageId: 'javascript',
    debounceMs: 200,
    render: renderCompiledOutput,
  });
}

async function renderCompiledOutput(document: vscode.TextDocument): Promise<string> {
  const dev = vscode.workspace.getConfiguration('owt', document.uri).get<boolean>('compiledOutput.dev', false);
  const filename = document.uri.scheme === 'file' ? document.uri.fsPath : document.uri.path;
  const name = basename(document.uri);
  let compiler: Compiler;
  try {
    compiler = await loadCompiler();
  } catch (err) {
    compilerPromise = undefined;
    return `// The OWT compiler could not be loaded: ${errorMessage(err)}\n`;
  }
  let result: CompileResult;
  try {
    result = compiler.compile(document.getText(), { filename, dev });
  } catch (err) {
    return formatCompileError(document, name, err);
  }
  return formatResult(document, name, dev, result);
}

function formatResult(document: vscode.TextDocument, name: string, dev: boolean, result: CompileResult): string {
  const header = [`// Compiled output of ${name}${dev ? ' (dev)' : ''} — read-only, updates as you type.`];
  if (result.warnings.length > 0) {
    header.push(`// ${result.warnings.length} warning${result.warnings.length === 1 ? '' : 's'}:`);
    for (const w of result.warnings) {
      header.push(`//   ${name}:${location(document, w.start)} ${oneLine(w.message)}`);
    }
  }
  let out = `${header.join('\n')}\n\n${result.js.code.trimEnd()}\n`;
  const css = result.css?.code.trim();
  if (css) {
    out += `\n/* ---------------------------------- CSS ----------------------------------\n${css.replaceAll('*/', '*\\/')}\n*/\n`;
  }
  return out;
}

function formatCompileError(document: vscode.TextDocument, name: string, err: unknown): string {
  const details = compileErrorDetails(err);
  const lines = [`// ${name} does not compile`, '//'];
  // the compiler's CompileError messages may already end with `(file:line:column)`
  const hasLocation = /:\d+:\d+\)?\s*$/.test(details.message);
  const where = details.start === undefined || hasLocation ? '' : ` (${name}:${location(document, details.start)})`;
  lines.push(`// ${details.message}${where}`);
  if (details.frame !== undefined) {
    lines.push('//');
    for (const line of details.frame.split('\n')) lines.push(`//   ${line}`);
  }
  return `${lines.join('\n')}\n`;
}

type CompileErrorDetails = { message: string; start?: number; frame?: string };

function compileErrorDetails(err: unknown): CompileErrorDetails {
  if (typeof err !== 'object' || err === null) return { message: String(err) };
  const message: unknown = Reflect.get(err, 'message');
  const start: unknown = Reflect.get(err, 'start');
  const frame: unknown = Reflect.get(err, 'frame');
  const details: CompileErrorDetails = { message: typeof message === 'string' ? message : String(err) };
  if (typeof start === 'number') details.start = start;
  if (typeof frame === 'string' && frame.trim() !== '') details.frame = frame.trimEnd();
  return details;
}

function location(document: vscode.TextDocument, offset: number): string {
  const pos = document.positionAt(offset);
  return `${pos.line + 1}:${pos.character + 1}`;
}

function oneLine(text: string): string {
  return text.replace(/\s*\n\s*/g, ' ');
}

function basename(uri: vscode.Uri): string {
  const path = uri.path;
  return path.slice(path.lastIndexOf('/') + 1) || uri.toString(true);
}
